1	import { Hono } from "hono";
2	import type { Db } from "@paperclipai/db";
3	import { HttpError } from "../../../../server/src/errors.js";
4	import { extractRoutesFromRouter } from "./express-router-bridge.js";
5	
6	/**
7	 * Re-export the full ActorContext types from the server package.
8	 *
9	 * We import directly rather than duplicating because these types are pure
10	 * TypeScript interfaces with zero runtime code — Wrangler/esbuild strips them
11	 * at bundle time. If the server package ever gains Node-specific runtime
12	 * imports at the type-import level, move these to a shared `@paperclipai/http`
13	 * package (tracked as follow-up to PR #6).
14	 */
15	export type {
16	  ActorContext,
17	  ActorMembership,
18	  ActorSource,
19	  BoardActor,
20	  AgentActor,
21	  RequestCtx,
22	  Handler,
23	  RouteDefinition,
24	} from "../../../../server/src/http/types.js";
25	
26	import type {
27	  ActorContext,
28	  Handler,
29	  RequestCtx,
30	  RouteDefinition,
31	} from "../../../../server/src/http/types.js";
32	
33	/**
34	 * Minimal structural alias for the storage service dependency.
35	 * Avoids importing the Node-typed `StorageService` directly from the server
36	 * package while remaining structurally compatible at runtime.
37	 */
38	export interface StorageServiceLike {
39	  provider: string;
40	  putFile(input: unknown): Promise<unknown>;
41	  getObject(companyId: string, objectKey: string): Promise<unknown>;
42	  headObject(companyId: string, objectKey: string): Promise<unknown>;
43	  deleteObject(companyId: string, objectKey: string): Promise<void>;
44	}
45	
46	export interface MountRoutesOptions {
47	  db: Db;
48	  storage: StorageServiceLike;
49	  /**
50	   * Optional middleware that populates `ctx.actor` from the request.
51	   * Called before the route handler for every matched route.
52	   *
53	   * Return `null` to treat the request as unauthenticated.
54	   * Throw or return a `Response` to short-circuit with an error.
55	   */
56	  resolveActor?: (request: Request) => Promise<ActorContext | null>;
57	}
58	
59	/**
60	 * Maps an `HttpError` (from `server/src/errors.ts`) to the appropriate HTTP
61	 * response. All other thrown values become 500 Internal Server Error.
62	 */
63	function errorResponse(err: unknown): Response {
64	  if (err instanceof HttpError) {
65	    return Response.json(
66	      { error: err.message, ...(err.details !== undefined ? { details: err.details } : {}) },
67	      { status: err.status },
68	    );
69	  }
70	  console.error(
71	    `[HonoAdapter] Unhandled error: ${err instanceof Error ? err.stack ?? err.message : String(err)}`,
72	  );
73	  return Response.json({ error: "Internal Server Error" }, { status: 500 });
74	}
75	
76	/**
77	 * Mounts an array of `RouteDefinition` objects onto a Hono app.
78	 *
79	 * Each route definition is a transport-agnostic handler (from the
80	 * `server/src/http/types.ts` seam). This function bridges from the Hono
81	 * request context to the `RequestCtx` shape those handlers expect.
82	 */
83	export function mountRoutes(
84	  app: Hono,
85	  routes: RouteDefinition[],
86	  options: MountRoutesOptions,
87	): void {
88	  const { db, storage, resolveActor } = options;
89	
90	  for (const route of routes) {
91	    const method = route.method.toLowerCase() as "get" | "post" | "put" | "patch" | "delete";
92	
93	    app[method](route.path, async (c) => {
94	      // Resolve actor from request (auth middleware equivalent)
95	      const actor = resolveActor ? await resolveActor(c.req.raw) : null;
96	
97	      const ctx: RequestCtx = {
98	        method: c.req.method,
99	        url: new URL(c.req.url),
100	        headers: new Headers(c.req.raw.headers),
101	
102	        async json<T>(): Promise<T> {
103	          return c.req.json<T>();
104	        },
105	
106	        async text(): Promise<string> {
107	          return c.req.text();
108	        },
109	
110	        param(name: string): string | undefined {
111	          return c.req.param(name);
112	        },
113	
114	        query(name: string): string | undefined {
115	          return c.req.query(name);
116	        },
117	
118	        actor,
119	        db,
120	        storage: storage as import("../../../../server/src/storage/types.js").StorageService,
121	      };
122	
123	      try {
124	        return await route.handler(ctx);
125	      } catch (err) {
126	        return errorResponse(err);
127	      }
128	    });
129	  }
130	}
131	
132	/**
133	 * Walks an Express Router's `.stack`, extracts all tagged route definitions
134	 * (those whose innermost handler carries `__handler` set by `expressHandler`),
135	 * and mounts them on the Hono app via `mountRoutes`.
136	 *
137	 * @param app      - The Hono application instance.
138	 * @param router   - An Express `Router` instance (opaque `unknown` to avoid
139	 *                   importing Express types into this Workers-safe file).
140	 * @param prefix   - Optional path prefix to prepend to every extracted route.
141	 *                   Use `"/companies"` for the company router, `""` for all
142	 *                   others (matches the `api.use("/companies", ...)` pattern
143	 *                   in `server/src/app.ts`).
144	 * @param options  - Same options passed to `mountRoutes`.
145	 */
146	export function mountExpressRouter(
147	  app: Hono,
148	  router: unknown,
149	  prefix: string,
150	  options: MountRoutesOptions,
151	): void {
152	  const routes = extractRoutesFromRouter(router, prefix);
153	  mountRoutes(app, routes, options);
154	}
